<?php

declare(strict_types=1);

namespace Moat\Gate\Tests\Conformance;

use Moat\Gate\Json\StrictJson;

/** Reads the shared vectors in conformance/vectors/ (generated by `pnpm vectors`). */
final class Vectors
{
    /** @param string $file relative to conformance/vectors/, e.g. `crypto/bundle.json` */
    public static function read(string $file): string
    {
        $path = \dirname(__DIR__, 4) . '/conformance/vectors/' . $file;
        $text = file_get_contents($path);
        if ($text === false) {
            throw new \RuntimeException("cannot read {$path}");
        }

        return $text;
    }

    /** @return array<string, mixed> */
    public static function load(string $file): array
    {
        $data = json_decode(self::read($file), true, 512, JSON_THROW_ON_ERROR);
        if (!\is_array($data)) {
            throw new \RuntimeException("{$file} is not an object");
        }

        /** @var array<string, mixed> $data */
        return $data;
    }

    /**
     * The cases as PHPUnit data: name → [case].
     *
     * @return iterable<string, array{array<string, mixed>}>
     */
    public static function cases(string $file, string $group = 'cases'): iterable
    {
        $cases = self::load($file)[$group] ?? null;
        if (!\is_array($cases)) {
            throw new \RuntimeException("{$file} has no cases");
        }
        foreach ($cases as $case) {
            $name = \is_array($case) ? ($case['name'] ?? null) : null;
            if (!\is_array($case) || !\is_string($name)) {
                throw new \RuntimeException("{$file} has a case without a name");
            }
            /** @var array<string, mixed> $case */
            yield $name => [$case];
        }
    }

    /**
     * A member of a case as the gate would decode it from bundle or policy bytes: objects stay
     * JsonObject, so `{}` and `[]` remain different (assoc arrays cannot tell them apart).
     */
    public static function strict(string $file, string $name, string $key): mixed
    {
        $data = json_decode(self::read($file), false, 512, JSON_THROW_ON_ERROR);
        $cases = $data instanceof \stdClass && \is_array($data->cases ?? null) ? $data->cases : [];
        foreach ($cases as $case) {
            $members = $case instanceof \stdClass ? get_object_vars($case) : [];
            if (($members['name'] ?? null) === $name && \array_key_exists($key, $members)) {
                return StrictJson::decode(json_encode($members[$key], JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
            }
        }

        throw new \RuntimeException("{$file} has no case {$name} with {$key}");
    }

    public static function string(mixed $value): string
    {
        if (!\is_string($value)) {
            throw new \RuntimeException('expected a string in the vector file');
        }

        return $value;
    }

    public static function int(mixed $value): int
    {
        if (!\is_int($value)) {
            throw new \RuntimeException('expected an integer in the vector file');
        }

        return $value;
    }

    /** @return array<mixed> */
    public static function list(mixed $value): array
    {
        if (!\is_array($value)) {
            throw new \RuntimeException('expected an array in the vector file');
        }

        return $value;
    }

    /** @return array<string, mixed> */
    public static function map(mixed $value): array
    {
        if (!\is_array($value)) {
            throw new \RuntimeException('expected an object in the vector file');
        }

        /** @var array<string, mixed> $value */
        return $value;
    }
}
